        machineTranslated: json['machineTranslated'] == null ? null : json['machineTranslated'] as bool,
        model: json['model'] == null ? null : json['model'] as String,
        promptVersion: json['promptVersion'] == null ? null : json['promptVersion'] as String,
        latencyMs: json['latencyMs'] == null ? null : json['latencyMs'] as int,
      );

  Map<String, dynamic> toJson() => {
        'text': text,
        'from': from.wire,
        'to': to.wire,
        if (machineTranslated != null) 'machineTranslated': machineTranslated!,
        if (model != null) 'model': model!,
        if (promptVersion != null) 'promptVersion': promptVersion!,
        if (latencyMs != null) 'latencyMs': latencyMs!,
      };
}

/// What a harm classifier decided about one message. category and severity are absent when harmful is false.
class Verdict {
  const Verdict({required this.harmful, this.category, this.severity, required this.confidence});

  final bool harmful;
  final HarmCategory? category;
  final Severity? severity;
  final double confidence;

  factory Verdict.fromJson(Map<String, dynamic> json) => Verdict(
        harmful: json['harmful'] as bool,
        category: json['category'] == null ? null : HarmCategory.fromWire(json['category'] as String),
        severity: json['severity'] == null ? null : Severity.fromWire(json['severity'] as String),
        confidence: (json['confidence'] as num).toDouble(),
      );

  Map<String, dynamic> toJson() => {
        'harmful': harmful,
        if (category != null) 'category': category!.wire,
        if (severity != null) 'severity': severity!.wire,
        'confidence': confidence,
      };
}

class VerifyResponse {
  const VerifyResponse({required this.hash, required this.found, this.timestamp, this.chainValid});

  final String hash;
  final bool found;
  final String? timestamp;
  final bool? chainValid;

  factory VerifyResponse.fromJson(Map<String, dynamic> json) => VerifyResponse(
        hash: json['hash'] as String,
        found: json['found'] as bool,
        timestamp: json['timestamp'] == null ? null : json['timestamp'] as String,
        chainValid: json['chainValid'] == null ? null : json['chainValid'] as bool,
      );

  Map<String, dynamic> toJson() => {
        'hash': hash,
        'found': found,
        if (timestamp != null) 'timestamp': timestamp!,
        if (chainValid != null) 'chainValid': chainValid!,
      };
}

/// Base of every event payload.
sealed class EventPayload {
  const EventPayload();
  Map<String, dynamic> toJson();
}

/// May leave the phone.
abstract class CloudSendablePayload extends EventPayload {
  const CloudSendablePayload();
}

/// Must never leave the phone.
abstract class PhoneOnlyPayload extends EventPayload {
  const PhoneOnlyPayload();
}

/// Static description of one event type.
class EventSpec<P extends EventPayload> {
  const EventSpec(this.type, this.version, this.publisher, this.where, this.phoneOnly, this.fromJson);
  final String type;
  final int version;
  final String publisher;
  final String where;
  final bool phoneOnly;
  final P Function(Map<String, dynamic>) fromJson;
}

/// Wraps every event.
class Envelope<P extends EventPayload> {
  const Envelope({required this.eventId, required this.type, required this.version, required this.occurredAt,
      required this.deviceId, this.caseId, required this.payload});
  final String eventId;
  final String type;
  final int version;
  final String occurredAt;
  final String deviceId;
  final String? caseId;
  final P payload;

  Map<String, dynamic> toJson() => {
        'eventId': eventId, 'type': type, 'version': version, 'occurredAt': occurredAt,
        'deviceId': deviceId, if (caseId != null) 'caseId': caseId, 'payload': payload.toJson(),
      };

  static Envelope<EventPayload> fromJson(Map<String, dynamic> json) {
    final spec = Events.byType(json['type'] as String, json['version'] as int);
    if (spec == null) throw ArgumentError('Unknown event ${json['type']}.v${json['version']}');
    return Envelope<EventPayload>(
      eventId: json['eventId'] as String,
      type: json['type'] as String,
      version: json['version'] as int,
      occurredAt: json['occurredAt'] as String,
      deviceId: json['deviceId'] as String,
      caseId: json['caseId'] as String?,
      payload: spec.fromJson(json['payload'] as Map<String, dynamic>),
    );
  }
}

abstract final class Events {
  static const EventSpec<CasefileCaseEscalatedPayload> casefileCaseEscalated = EventSpec('casefile.case.escalated', 1, 'casefile', 'phone_to_cloud', false, CasefileCaseEscalatedPayload.fromJson);
  static const EventSpec<CasefileCaseUpdatedPayload> casefileCaseUpdated = EventSpec('casefile.case.updated', 1, 'casefile', 'phone_to_cloud', false, CasefileCaseUpdatedPayload.fromJson);
  static const EventSpec<CasefileEvidenceReadyPayload> casefileEvidenceReady = EventSpec('casefile.evidence.ready', 1, 'casefile', 'phone', true, CasefileEvidenceReadyPayload.fromJson);
  static const EventSpec<CasefileEvidenceSealedPayload> casefileEvidenceSealed = EventSpec('casefile.evidence.sealed', 1, 'casefile', 'phone', false, CasefileEvidenceSealedPayload.fromJson);
  static const EventSpec<CasefileReportReadyPayload> casefileReportReady = EventSpec('casefile.report.ready', 1, 'casefile', 'phone', true, CasefileReportReadyPayload.fromJson);
  static const EventSpec<CasefileShareCompletedPayload> casefileShareCompleted = EventSpec('casefile.share.completed', 1, 'casefile', 'cloud', false, CasefileShareCompletedPayload.fromJson);
  static const EventSpec<CasefileShareRequestedPayload> casefileShareRequested = EventSpec('casefile.share.requested', 1, 'casefile', 'phone_to_cloud', false, CasefileShareRequestedPayload.fromJson);
  static const EventSpec<CompanionAdviceShownPayload> companionAdviceShown = EventSpec('companion.advice.shown', 1, 'companion', 'phone_to_cloud', false, CompanionAdviceShownPayload.fromJson);
  static const EventSpec<CompanionCaptureRequestedPayload> companionCaptureRequested = EventSpec('companion.capture.requested', 1, 'companion', 'phone', false, CompanionCaptureRequestedPayload.fromJson);
  static const EventSpec<CompanionFeedbackSubmittedPayload> companionFeedbackSubmitted = EventSpec('companion.feedback.submitted', 1, 'companion', 'phone', false, CompanionFeedbackSubmittedPayload.fromJson);
  static const EventSpec<CompanionSosTriggeredPayload> companionSosTriggered = EventSpec('companion.sos.triggered', 1, 'companion', 'phone_to_cloud', false, CompanionSosTriggeredPayload.fromJson);
  static const EventSpec<GuardianAlertSentPayload> guardianAlertSent = EventSpec('guardian.alert.sent', 1, 'guardian', 'cloud', false, GuardianAlertSentPayload.fromJson);
  static const EventSpec<GuardianEvidenceRequestedPayload> guardianEvidenceRequested = EventSpec('guardian.evidence.requested', 1, 'guardian', 'phone', true, GuardianEvidenceRequestedPayload.fromJson);
  static const EventSpec<GuardianPairingCompletedPayload> guardianPairingCompleted = EventSpec('guardian.pairing.completed', 1, 'guardian', 'cloud_to_phone', false, GuardianPairingCompletedPayload.fromJson);
  static const EventSpec<GuardianPolicyUpdatedPayload> guardianPolicyUpdated = EventSpec('guardian.policy.updated', 1, 'guardian', 'cloud_to_phone', false, GuardianPolicyUpdatedPayload.fromJson);
  static const EventSpec<GuardianReportRequestedPayload> guardianReportRequested = EventSpec('guardian.report.requested', 1, 'guardian', 'phone', true, GuardianReportRequestedPayload.fromJson);
  static const EventSpec<GuardianShareApprovedPayload> guardianShareApproved = EventSpec('guardian.share.approved', 1, 'guardian', 'cloud_to_phone', false, GuardianShareApprovedPayload.fromJson);
  static const EventSpec<GuardianShareDeclinedPayload> guardianShareDeclined = EventSpec('guardian.share.declined', 1, 'guardian', 'cloud_to_phone', false, GuardianShareDeclinedPayload.fromJson);
  static const EventSpec<SentinelCaptureReadyPayload> sentinelCaptureReady = EventSpec('sentinel.capture.ready', 1, 'sentinel', 'phone', true, SentinelCaptureReadyPayload.fromJson);
  static const EventSpec<SentinelConversationActivePayload> sentinelConversationActive = EventSpec('sentinel.conversation.active', 1, 'sentinel', 'phone', true, SentinelConversationActivePayload.fromJson);
  static const EventSpec<SentinelFlagUpdatedPayload> sentinelFlagUpdated = EventSpec('sentinel.flag.updated', 1, 'sentinel', 'phone', false, SentinelFlagUpdatedPayload.fromJson);
  static const EventSpec<SentinelMessageFlaggedPayload> sentinelMessageFlagged = EventSpec('sentinel.message.flagged', 1, 'sentinel', 'phone', false, SentinelMessageFlaggedPayload.fromJson);

  static const List<EventSpec<EventPayload>> all = [
    casefileCaseEscalated,
    casefileCaseUpdated,
    casefileEvidenceReady,
    casefileEvidenceSealed,
    casefileReportReady,
    casefileShareCompleted,
    casefileShareRequested,
    companionAdviceShown,
    companionCaptureRequested,
    companionFeedbackSubmitted,
    companionSosTriggered,
    guardianAlertSent,
    guardianEvidenceRequested,
    guardianPairingCompleted,
    guardianPolicyUpdated,
    guardianReportRequested,
    guardianShareApproved,
    guardianShareDeclined,
    sentinelCaptureReady,
    sentinelConversationActive,
    sentinelFlagUpdated,
    sentinelMessageFlagged,
  ];

  static EventSpec<EventPayload>? byType(String type, int version) {
    for (final s in all) {
      if (s.type == type && s.version == version) return s;
    }
    return null;
  }
}
